INSERT INTO `act_ge_bytearray` VALUES ('b2c6351a-bff6-11f1-8cd9-d8bbc1e55a1a',1,'CLAIM.bpmn20.xml','b2c63519-bff6-11f1-8cd9-d8bbc1e55a1a',_binary '<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<bpmn:definitions xmlns:bpmn=\"http://www.omg.org/spec/BPMN/20100524/MODEL\" xmlns:bpmndi=\"http://www.omg.org/spec/BPMN/20100524/DI\" xmlns:dc=\"http://www.omg.org/spec/DD/20100524/DC\" xmlns:di=\"http://www.omg.org/spec/DD/20100524/DI\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xmlns:flowable=\"http://flowable.org/bpmn\" id=\"Definitions_CLAIM\" targetNamespace=\"http://fssc\">\n  <bpmn:process id=\"CLAIM\" name=\"审核预制凭证\" isExecutable=\"true\">\n    <bpmn:startEvent id=\"StartEvent_1\" name=\"开始\" />\n    <bpmn:exclusiveGateway id=\"Gw_ENT\" name=\"招待费特批档\" default=\"Flow_in_Task_2\" />\n    <bpmn:sequenceFlow id=\"Flow_start_gw\" sourceRef=\"StartEvent_1\" targetRef=\"Gw_ENT\" />\n    <bpmn:userTask id=\"Task_2\" name=\"扫描单据【财务扫描岗】\" flowable:candidateGroups=\"SCAN_STAFF\" />\n    <bpmn:sequenceFlow id=\"Flow_in_Task_2\" sourceRef=\"Gw_ENT\" targetRef=\"Task_2\" />\n    <bpmn:userTask id=\"Task_4\" name=\"直接上级审核【直线上级】\" flowable:candidateGroups=\"DIRECT_SUPERVISOR\" />\n    <bpmn:sequenceFlow id=\"Flow_in_Task_4\" sourceRef=\"Task_2\" targetRef=\"Task_4\" />\n    <bpmn:userTask id=\"Task_5\" name=\"部门经理审核【部门经理】\" flowable:candidateGroups=\"DEPT_MANAGER\" />\n    <bpmn:sequenceFlow id=\"Flow_in_Task_5\" sourceRef=\"Task_4\" targetRef=\"Task_5\" />\n    <bpmn:userTask id=\"Task_6\" name=\"项目经理审核【项目经理/费用承担部门负责人】\" flowable:candidateGroups=\"PROJECT_MANAGER\" />\n    <bpmn:sequenceFlow id=\"Flow_in_Task_6\" sourceRef=\"Task_5\" targetRef=\"Task_6\" />\n    <bpmn:userTask id=\"Task_7\" name=\"财务共享审核单据【共享会计】\" flowable:candidateGroups=\"FSSC_AUDITOR\" />\n    <bpmn:sequenceFlow id=\"Flow_in_Task_7\" sourceRef=\"Task_6\" targetRef=\"Task_7\" />\n    <bpmn:exclusiveGateway id=\"Gw_16\" name=\"金额授权\" default=\"Flow_in_Gw_9\" />\n    <bpmn:sequenceFlow id=\"Flow_in_Gw_16